import {esc,money} from '../config.mjs';
const date=v=>v?new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Ainda não';
export function senderCards(items,now=Date.now()){
 return items.filter(x=>Date.parse(x.expiresAt)>now).map(x=>`<article class="paper sender-record" data-expires="${esc(x.expiresAt)}"><div class="row wrap"><h2>${esc(x.fullName)}</h2><strong>${esc(x.code)}</strong></div><dl class="private-details">${[['Modalidade',({video:'Vídeo oficial',community:'Comunidade',live:'LIVE'})[x.purchase?.modality]||'Não registrada'],['Valor',money(x.purchase?.priceCents||0)],['Mensagem',x.purchase?.message||'Conteúdo não registrado'],['Nome completo informado',x.fullName],['Telefone informado',x.phone],['IP observado',x.ip],['Pagamento confirmado',date(x.confirmedAt)],['Disponível até',date(x.expiresAt)]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl></article>`).join('')||'<div class="empty">Nenhum pedido aprovado e pago neste período.</div>';
}
export function reactivationMarkup(d){
 const conversion=d.sent30?((d.conversions/d.sent30)*100).toFixed(1)+'%':'—';
 return `<div class="note"><strong>${d.channelReady?'Notificações do app configuradas':'Notificações do app indisponíveis'}</strong><p>${d.channelReady?'O servidor verifica ausências e autorizações a cada cinco minutos. O envio usa push do próprio app.':'O serviço push está indisponível. Os avisos não usam WhatsApp e nenhum envio será simulado.'}</p></div><div class="metrics">${[['Elegíveis',d.eligible],['Enviadas hoje',d.sentToday],['Retornos · 30 dias',d.returns],['Conversão · 30 dias',conversion],['Pausadas',d.paused],['Falhas · 30 dias',d.failures]].map(([label,n])=>`<div class="metric"><b>${esc(n??0)}</b><span>${label}</span></div>`).join('')}</div><p class="hint">Retorno = abertura neste navegador após um aviso aceito pelo serviço push. Conversão = pagamento posterior ao retorno, em até 7 dias. A taxa usa os envios dos últimos 30 dias; não prova causalidade. Aceitação pelo serviço push não garante exibição ou leitura no aparelho.</p><div class="orders">${(d.items||[]).map(x=>`<article class="order"><h2>${esc(x.name)}</h2><dl class="private-details">${[['Origem',x.origin],['Última atividade',date(x.lastActivity)],['Última notificação',date(x.lastNotification)],['Enviadas ao serviço push',x.received],['Retornos',x.returns],['Próxima verificação',x.enabled&&x.failureCount<3?date(x.nextSend):'Pausada'],['Situação',!x.enabled?'Comunicações desativadas':x.failureCount>=3?'Pausada por falhas':'Autorizada'],['Última falha',x.lastError||'Nenhuma']].map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join('')}</dl></article>`).join('')||'<div class="empty">Ainda não há pessoas com autorização de retorno registrada.</div>'}</div>`;
}
export function mountPrivateQueue(host,call,kind){
 let disposed=false,busy=false,offset=0,search='',generation=0;
 host.innerHTML=`<section><h1>${kind==='senders'?'Remetentes · 48h':'Reativação'}</h1><p class="hint">${kind==='senders'?'Pedidos aprovados e pagos. Prazo de 48 horas a partir da primeira confirmação do pagamento. Consultas registradas automaticamente. Nome e telefone são declarados; IP não comprova identidade.':'Primeiro retorno após 48h de ausência; mais duas tentativas espaçadas em 48h, depois intervalo de 14 dias. A visita reinicia o ciclo. Apenas aparelhos que permitiram notificações.'}</p>${kind==='senders'?'<form data-queue-search><label for="sender-search">Buscar nome ou código</label><input id="sender-search" name="search" maxlength="120" placeholder="Nome completo ou código"><button class="btn" type="submit">Buscar</button></form>':''}<div data-queue-error role="alert"></div><div data-queue-content>Carregando…</div><div class="actions"><button class="btn secondary" data-queue-prev>Anterior</button><span data-queue-page></span><button class="btn secondary" data-queue-next>Próxima</button><button class="btn" data-queue-refresh>Atualizar</button></div></section>`;
 const q=s=>host.querySelector(s),content=q('[data-queue-content]');
 async function load(){if(disposed||busy)return;busy=true;const current=++generation;q('[data-queue-error]').textContent='';try{const d=await call(kind==='senders'?'admin.sender.list':'admin.reactivation',{offset,search});if(disposed||current!==generation)return;content.innerHTML=kind==='senders'?senderCards(d.items||[]):reactivationMarkup(d);q('[data-queue-prev]').disabled=offset===0;q('[data-queue-next]').disabled=offset+50>=d.total;q('[data-queue-page]').textContent=`${d.total?offset+1:0}–${Math.min(offset+50,d.total)} de ${d.total}`;}catch(e){if(!disposed)q('[data-queue-error]').textContent=e.message}finally{busy=false}}
 q('[data-queue-prev]').onclick=()=>{if(busy)return;offset=Math.max(0,offset-50);load()};q('[data-queue-next]').onclick=()=>{if(busy)return;offset+=50;load()};q('[data-queue-refresh]').onclick=load;
 q('[data-queue-search]')?.addEventListener('submit',e=>{e.preventDefault();if(busy)return;offset=0;search=String(new FormData(e.target).get('search')||'').trim();load()});
 load();const expiry=setInterval(()=>{if(disposed)return;host.querySelectorAll('[data-expires]').forEach(el=>{if(Date.parse(el.dataset.expires)<=Date.now())el.remove()})},1000);
 return ()=>{disposed=true;generation++;clearInterval(expiry);host.replaceChildren()};
}
